import{_ as t,o as i,c as e,ag as s}from"./chunks/framework.D9ghT4bC.js";const k=JSON.parse('{"title":"UncivCN 分支介绍","description":"","frontmatter":{"title":"UncivCN 分支介绍"},"headers":[],"relativePath":"zh/UncivCN/index.md","filePath":"zh/UncivCN/index.md"}'),n={name:"zh/UncivCN/index.md"};function r(l,a,h,d,o,c){return i(),e("div",null,[...a[0]||(a[0]=[s(`<h1 id="uncivcn-分支介绍" tabindex="-1">UncivCN 分支介绍 <a class="header-anchor" href="#uncivcn-分支介绍" aria-label="Permalink to &quot;UncivCN 分支介绍&quot;">​</a></h1><h2 id="这是什么" tabindex="-1">这是什么 <a class="header-anchor" href="#这是什么" aria-label="Permalink to &quot;这是什么&quot;">​</a></h2><p><strong>UncivCN</strong> 是开源游戏 <a href="https://github.com/yairm210/Unciv" target="_blank" rel="noreferrer">Unciv</a>（LibGDX 编写的《文明5》复刻，支持 Android / Desktop / Server）的社区分支， 针对中文玩家深度定制：在原版基础上新增联机、地图、模组、UI 等多项特性，并完整跟进上游更新。</p><ul><li>上游仓库：<a href="https://github.com/yairm210/Unciv" target="_blank" rel="noreferrer">https://github.com/yairm210/Unciv</a></li><li>UncivCN 仓库：<a href="https://github.com/AutumnPizazz/Unciv" target="_blank" rel="noreferrer">https://github.com/AutumnPizazz/Unciv</a></li><li></li></ul><h2 id="与上游的关系" tabindex="-1">与上游的关系 <a class="header-anchor" href="#与上游的关系" aria-label="Permalink to &quot;与上游的关系&quot;">​</a></h2><ul><li><strong>同步跟进</strong>：定期将上游 master 合并进 UncivCN，游戏版本号 = 上游版本 + CN 子版本号（如 4.21.5 → 4.21.5.1；同一上游版本可发 .1/.2/.3…，如 4.20.8.1 → 4.20.8.4），始终基于最新上游开发</li><li><strong>CN 独有改动</strong>：所有 UncivCN 特性均以增量方式实现，上游功能不受影响</li><li><strong>分道扬镳</strong>：UncivCN 自 2026 年从上游独立演进（<a href="https://github.com/AutumnPizazz/Unciv/commit/4c23bb4dc" target="_blank" rel="noreferrer">4c23bb4dc</a>），拥有独立版本号与发布节奏</li></ul><h2 id="主要特性速览" tabindex="-1">主要特性速览 <a class="header-anchor" href="#主要特性速览" aria-label="Permalink to &quot;主要特性速览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类别</th><th>特性</th></tr></thead><tbody><tr><td>联机</td><td><a href="./Polling-multiplayer.html">轮询联机</a>、默认服务器（sp.unciv.cn）、联机禁用读档随机数</td></tr><tr><td>地图</td><td>三种镜像地图模式、环形地图、取消半径奇偶限制</td></tr><tr><td>模组</td><td><a href="./Features.html#lua-模组系统-4-20-8-2-起-持续增强">Lua 脚本</a>、<a href="./Features.html#mergeaction-扩展-json-系统-4-20-7-3">MergeAction 扩展 JSON 系统</a>、tile-claim 地块归属、<a href="./Mod-download-in-China.html">国内镜像下载源</a></td></tr><tr><td>UI</td><td>单位钉/地图钉、人口自动锁定按钮、设置导出/导入剪贴板</td></tr><tr><td>其他</td><td>游戏版本兼容性隔离、随机数读档可变（单机）</td></tr></tbody></table><p>详细说明见 <a href="./Features.html">新特性</a> 与 <a href="./Differences.html">与上游差异</a>。</p><h2 id="构建方式" tabindex="-1">构建方式 <a class="header-anchor" href="#构建方式" aria-label="Permalink to &quot;构建方式&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./gradlew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> desktop:run</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 运行桌面版</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./gradlew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> :tests:test</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 运行全部测试</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./gradlew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> desktop:dist</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # 构建 JAR → desktop/build/libs/Unciv.jar</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./gradlew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server:run</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # 运行多人服务器</span></span></code></pre></div><p>Android 构建需 <code>local.properties</code>（<code>sdk.dir</code>）或 <code>ANDROID_HOME</code> 环境变量。</p><p>版本号定义在 <code>buildSrc/src/main/kotlin/BuildConfig.kt</code>，变更记录见 <a href="./Changelog.html">更新日志</a>。</p>`,13)])])}const u=t(n,[["render",r]]);export{k as __pageData,u as default};
